def minimize_dfa(states, alphabet, transition, start, finals):
    # 1. mark unreachable states
    reachable = set()
    stack = [start]
    while stack:
        s = stack.pop()
        if s in reachable: continue
        reachable.add(s)
        for a in alphabet:
            stack.append(transition[s][a])
    # 2. initialize table
    n = len(states)
    table = [[False]*n for _ in range(n)]
    idx = {s:i for i,s in enumerate(states)}
    # mark pairs (p,q) where one is final and other is not
    for i in range(n):
        for j in range(i):
            p, q = states[i], states[j]
            if (p in finals) != (q in finals):
                table[i][j] = True
    # 3. propagate distinctions
    changed = True
    while changed:
        changed = False
        for i in range(n):
            for j in range(i):
                if table[i][j]: continue
                for a in alphabet:
                    pi, pj = transition[states[i]][a], transition[states[j]][a]
                    x, y = idx[pi], idx[pj]
                    if x==y: continue
                    if x<y:
                        if table[x][y]:
                            table[i][j] = True; changed=True; break
                    else:
                        if table[y][x]:
                            table[i][j] = True; changed=True; break
    # 4. build equivalence classes
    parent = {s:s for s in states}
    def find(s):
        while parent[s]!=s:
            parent[s]=parent[parent[s]]; s=parent[s]
        return s
    def union(a,b):
        ra, rb = find(a), find(b)
        if ra!=rb: parent[rb]=ra
    for i in range(n):
        for j in range(i):
            if not table[i][j]:
                union(states[i], states[j])
    # 5. construct new DFA (omitted for brevity)
    return parent  # mapping to representative state

code.src:
Find epsilon-closure for State q0 in the following NFA:
Transitions:
- delta(q0, eps) = {q1, q2}
- delta(q1, eps) = {q3}
- delta(q2, a)   = {q4}

Step-by-step Epsilon-Closure of q0:
1. Start with {q0}
2. From q0 on eps, we reach q1 and q2 -> Set becomes {q0, q1, q2}
3. From q1 on eps, we reach q3 -> Set becomes {q0, q1, q2, q3}
4. From q2, there is no eps transition (only 'a'). Stop.

Result: Epsilon-Closure(q0) = {q0, q1, q2, q3}

