def compute_epsilon_closure(state, transitions):
    closure = {state}
    stack = [state]
    while stack:
        curr = stack.pop()
        for next_state in transitions.get((curr, 'eps'), []):
            if next_state not in closure:
                closure.add(next_state)
                stack.append(next_state)
    return closure

def simulate_dfa(transitions, start_state, accept_states, string):
    current = start_state
    for char in string:
        current = transitions.get((current, char))
        if current is None:
            return False
    return current in accept_states

