def mealy_01_detector(inputs):
    state = 'S0'
    outputs = []
    for bit in inputs:
        if state == 'S0':
            if bit == '0':
                state = 'S1'
                outputs.append(0)
            else:
                state = 'S0'
                outputs.append(0)
        elif state == 'S1':
            if bit == '1':
                state = 'S0'
                outputs.append(1) # Detected '01'
            else:
                state = 'S1'
                outputs.append(0)
    return outputs
print(mealy_01_detector([0, 1, 0, 1, 0]))

def moore_machine(inputs):
    # State outputs: S0->0, S1->0, S2->1
    state = 'S0'
    outputs = []
    output_map = {'S0': 0, 'S1': 0, 'S2': 1}
    for bit in inputs:
        outputs.append(output_map[state])
        if state == 'S0' and bit == 1:
            state = 'S1'
        elif state == 'S1' and bit == 1:
            state = 'S2'
        else:
            state = 'S0'
    return outputs

def moore_to_mealy(moore_transitions, state_outputs):
    mealy_transitions = {}
    for state, transitions in moore_transitions.items():
        mealy_transitions[state] = {}
        for inp, next_state in transitions.items():
            # Output comes from the destination state's output in Moore
            out = state_outputs[next_state]
            mealy_transitions[state][inp] = (next_state, out)
    return mealy_transitions

