def is_type3(lhs, rhs):
    if len(lhs) == 1 and lhs.isupper():
        if len(rhs) == 1 and rhs.islower(): return True
        if len(rhs) == 2 and rhs[0].islower() and rhs[1].isupper(): return True
    return False
print(is_type3('S', 'aA')) # True

def check_brackets(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack: return False
            stack.pop()
    return len(stack) == 0
print(check_brackets('(()())')) # True

