# Simulating a simple PDA recognizing L = {a^n b^n | n >= 0}
class SimplePDA:
    def __init__(self):
        self.stack = ['Z0'] # Z0 is initial stack symbol

    def process(self, string):
        state = 'q0'
        for char in string:
            if char == 'a':
                self.stack.append('A') # Push 'A' for every 'a'
            elif char == 'b':
                if len(self.stack) > 1 and self.stack[-1] == 'A':
                    self.stack.pop() # Pop 'A' for every 'b'
                else:
                    return False
        return self.stack == ['Z0']

pda = SimplePDA()
print(pda.process("aabb")) # Expected: True

