def solve_pcp(A, B, current_seq=[], depth=0, max_depth=5):
    if depth > max_depth: return None
    if len(current_seq) > 0:
        top = ''.join(A[i] for i in current_seq)
        bottom = ''.join(B[i] for i in current_seq)
        if top == bottom: return current_seq
    for i in range(len(A)):
        res = solve_pcp(A, B, current_seq + [i], depth + 1, max_depth)
        if res: return res
    return None

